<script setup lang="ts">
import {ref} from 'vue';import {api,post,type Failures} from '../api';import {usePoll} from '../composables/poll';import {useAuth} from '../stores/auth';import {money,time} from '../money';import DataState from '../components/DataState.vue';import StatusBadge from '../components/StatusBadge.vue';
const filter=ref('');function matches(row:unknown){return !filter.value||JSON.stringify(row).toLowerCase().includes(filter.value.toLowerCase())}const auth=useAuth();const state=usePoll(signal=>api<Failures>('/failures',{signal}));const reference=ref('LOAN-1001');const error=ref('');const busy=ref(false);
async function action(path:string,body?:unknown){busy.value=true;error.value='';try{await post(path,body);await state.refresh()}catch(e){error.value=e instanceof Error?e.message:'Action failed'}finally{busy.value=false}}
</script>
<template><div class="page-title"><div><p class="eyebrow">VISIBLE OUTCOMES · SAFE RECOVERY</p><h1>Failures & recovery</h1><p class="muted">Resolve references and replay under the original financial identity.</p></div></div><DataState :loading="state.loading.value" :error="state.error.value" :updated-at="state.updatedAt.value"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="state.data.value?.loan?.unavailable||state.data.value?.webhook?.unavailable" title="Some failure sources are unavailable" type="warning" :closable="false"/>
<label class="failure-filter">Filter loaded failures by identity, reference or reason<el-input v-model="filter" clearable placeholder="Search observed failures" class="search"/></label><section class="panel"><div class="panel-heading"><div><h3>Payments requiring review</h3><p>Posted credit requires manual review; replay cannot reduce principal early.</p></div><el-input v-if="auth.role==='Admin'" v-model="reference" placeholder="Resolution loan reference" class="search"/></div><el-table :data="(state.data.value?.loan?.reviews??[]).filter(matches)"><el-table-column prop="bankTransactionId" label="Original identity" min-width="265"/><el-table-column prop="originalReference" label="Received reference" min-width="165"/><el-table-column label="Amount" min-width="150"><template #default="{row}">{{money(row.amountMinor)}}</template></el-table-column><el-table-column label="Status / reason" min-width="270"><template #default="{row}"><StatusBadge :status="row.status"/><p>{{row.reason}}</p><small v-if="row.resolvedReference">Resolved to {{row.resolvedReference}}</small></template></el-table-column><el-table-column v-if="auth.role==='Admin'" label="Admin actions" min-width="190"><template #default="{row}"><el-button v-if="row.status==='Unmatched'" size="small" :disabled="busy" @click="action('/payments/'+row.bankTransactionId+'/resolve',{reference})">Resolve</el-button><el-button v-if="row.status==='Unmatched'" size="small" :disabled="busy||!row.resolvedReference" @click="action('/payments/'+row.bankTransactionId+'/replay')">Replay</el-button></template></el-table-column></el-table></section>
<section class="panel"><div class="panel-heading"><h3>Failed infrastructure messages</h3></div><el-table :data="(state.data.value?.loan?.failedMessages??[]).filter(matches)"><el-table-column prop="identity" label="Preserved identity" min-width="260"/><el-table-column prop="attempts" label="Attempts" width="100"/><el-table-column prop="reason" label="Reason" min-width="240"/><el-table-column label="Failed at" min-width="200"><template #default="{row}">{{time(row.failedAt)}}</template></el-table-column><el-table-column v-if="auth.role==='Admin'" label="Replay"><template #default="{row}"><el-button size="small" :disabled="busy||!!row.replayedAt" @click="action('/failures/'+row.id+'/replay')">{{row.replayedAt?'Queued':'Replay'}}</el-button></template></el-table-column></el-table></section>
<section class="panel"><div class="panel-heading"><h3>Identity & outcome conflicts</h3></div><el-table :data="(state.data.value?.loan?.conflicts??[]).filter(matches)"><el-table-column prop="bankTransactionId" label="Bank transaction" min-width="280"/><el-table-column prop="eventId" label="Event identity" min-width="260"/><el-table-column prop="reason" label="Review reason" min-width="320"/></el-table><el-table :data="(state.data.value?.webhook?.conflicts??[]).filter(matches)"><el-table-column prop="eventId" label="Conflicting webhook event" min-width="260"/><el-table-column prop="reason" label="Reason" min-width="320"/></el-table></section>
<section class="panel"><div class="panel-heading"><h3>Signed payload validation failures</h3></div><el-table :data="(state.data.value?.webhook?.validation??[]).filter(matches)"><el-table-column label="Observed at"><template #default="{row}">{{time(row.at)}}</template></el-table-column><el-table-column prop="reason" label="Validation reason"/></el-table></section>
<section class="panel"><div class="panel-heading"><h3>Operational audit trail</h3><span class="eyebrow">ACTOR · ORIGINAL IDENTITY · BEFORE / AFTER</span></div><el-table :data="[...(state.data.value?.loan?.audit??[]),...(Array.isArray(state.data.value?.simulatorAudit)?state.data.value.simulatorAudit:[])].sort((a,b)=>b.at.localeCompare(a.at))"><el-table-column label="At" min-width="190"><template #default="{row}">{{time(row.at)}}</template></el-table-column><el-table-column prop="actor" label="Actor" width="100"/><el-table-column prop="action" label="Action" min-width="180"/><el-table-column prop="identity" label="Original identity" min-width="260"/><el-table-column prop="details" label="Transition / mapping" min-width="200"/></el-table></section></template>
